Create Patient.code:
// Register a patient in the shared health record FHIR store.
createFhirResource(
  // 1) The target FHIR store (all four keys are required).
  {
    cloudRegion: 'europe-west4',
    projectId: 'moh-health-data',
    datasetId: 'national-hie',
    fhirStoreId: 'shr-r4',
  },
  // 2) The FHIR resource; resourceType decides the endpoint.
  {
    resourceType: 'Patient',
    identifier: [{ system: 'http://moh.example.org/national-id', value: $.data.nationalId }],
    name: [{ use: 'official', family: $.data.lastName, given: [$.data.firstName] }],
    gender: $.data.sex,
    birthDate: $.data.dateOfBirth,
  }
);

Create Encounter.code:
// Log an outpatient visit for an existing patient.
createFhirResource(
  // 1) The target FHIR store (all four keys are required).
  {
    cloudRegion: 'europe-west4',
    projectId: 'moh-health-data',
    datasetId: 'national-hie',
    fhirStoreId: 'shr-r4',
  },
  // 2) The Encounter, referencing the patient by id.
  {
    resourceType: 'Encounter',
    status: 'finished',
    class: { system: 'http://terminology.hl7.org/CodeSystem/v3-ActCode', code: 'AMB', display: 'ambulatory' },
    subject: { reference: `Patient/${$.data.patientId}` },
    period: { start: $.data.checkInTime, end: $.data.checkOutTime },
  }
);

Create Observation.code:
// Store an HIV viral load result from the lab system.
createFhirResource(
  // 1) The target FHIR store (all four keys are required).
  {
    cloudRegion: 'europe-west4',
    projectId: 'moh-health-data',
    datasetId: 'national-hie',
    fhirStoreId: 'shr-r4',
  },
  // 2) The Observation (LOINC 25836-8 = HIV-1 RNA viral load).
  {
    resourceType: 'Observation',
    status: 'final',
    code: { coding: [{ system: 'http://loinc.org', code: '25836-8' }] },
    subject: { reference: `Patient/${$.data.patientId}` },
    effectiveDateTime: $.data.sampleDate,
    valueQuantity: { value: $.data.copiesPerMl, unit: 'copies/mL' },
  }
);

Create Immunization.code:
// Record a measles vaccine dose given during an outreach campaign.
createFhirResource(
  // 1) The target FHIR store (all four keys are required).
  {
    cloudRegion: 'europe-west4',
    projectId: 'moh-health-data',
    datasetId: 'national-hie',
    fhirStoreId: 'shr-r4',
  },
  // 2) The Immunization (CVX 05 = measles).
  {
    resourceType: 'Immunization',
    status: 'completed',
    vaccineCode: { coding: [{ system: 'http://hl7.org/fhir/sid/cvx', code: '05' }] },
    patient: { reference: `Patient/${$.data.patientId}` },
    occurrenceDateTime: $.data.dateGiven,
    lotNumber: $.data.lotNumber,
  }
);

Create Condition.code:
// Record a confirmed malaria diagnosis.
createFhirResource(
  // 1) The target FHIR store (all four keys are required).
  {
    cloudRegion: 'europe-west4',
    projectId: 'moh-health-data',
    datasetId: 'national-hie',
    fhirStoreId: 'shr-r4',
  },
  // 2) The Condition, coded with ICD-10.
  {
    resourceType: 'Condition',
    clinicalStatus: { coding: [{ system: 'http://terminology.hl7.org/CodeSystem/condition-clinical', code: 'active' }] },
    verificationStatus: { coding: [{ system: 'http://terminology.hl7.org/CodeSystem/condition-ver-status', code: 'confirmed' }] },
    code: { coding: [{ system: 'http://hl7.org/fhir/sid/icd-10', code: 'B54', display: 'Unspecified malaria' }] },
    subject: { reference: `Patient/${$.data.patientId}` },
    onsetDateTime: $.data.diagnosisDate,
  }
);

Create Resources For Each Record.code:
// Create one Patient per record in an incoming list.
each(
  $.data.patients,
  createFhirResource(
    // 1) The target FHIR store (all four keys are required).
    {
      cloudRegion: 'europe-west4',
      projectId: 'moh-health-data',
      datasetId: 'national-hie',
      fhirStoreId: 'shr-r4',
    },
    // 2) Inside each(), $.data is the current item.
    {
      resourceType: 'Patient',
      name: [{ family: $.data.lastName, given: [$.data.firstName] }],
      birthDate: $.data.dateOfBirth,
    }
  )
);
